// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadCaveat = makeLoadFont('Caveat');

const { fontFamily: caveatFont } = loadCaveat();



export type ListAnimationProps = Record<string, any>;

const ListAnimation: React.FC<ListAnimationProps> = ({
  backgroundColor = "#f0f2f5",
  transparentBackground = false,
  durationInSeconds = 12,
  title = "The Structure I use for Every video",
  items = [
    { text: "hook" },
    { text: "problem" },
    { text: "story" },
    { text: "payoff" },
  ],
  notepadBg = "#ffffff",
  notepadBorder = "#2c2c2c",
  horizontalLineColor = "#d1d5db",
  verticalLineColor = "#fca5a5", 
  textColor = "#374151",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const notepadEntranceDur = 20;
  const lineDrawStart = 10;
  const titleDrawStart = 25;
  const listStart = 50;
  const itemStagger = 45; // Frames between each list item starting

  // Notepad entrance animation
  const notepadScale = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 80 },
    durationInFrames: notepadEntranceDur,
  });

  const notepadOpacity = interpolate(frame, [0, 10], [0, 1], { extrapolateRight: "clamp" });

  // Dimensions relative to canvas
  const padWidth = width * 0.85;
  const padHeight = height * 0.9;
  const padLeft = (width - padWidth) / 2;
  const padTop = (height - padHeight) / 2;

  // Layout calculations inside notepad
  const titleY = padHeight * 0.12;
  const firstLineY = padHeight * 0.25;
  const lineGap = padHeight * 0.12;
  const marginX = padWidth * 0.15; // Vertical red line position
  const contentStartX = marginX + 60; // Indent for list items

  // Draw vertical margin line
  const vertLineHeight = interpolate(frame, [lineDrawStart, lineDrawStart + 30], [0, padHeight], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center", fontFamily: caveatFont }}>
      
      {/* The Notepad */}
      <div
        style={{
          width: padWidth,
          height: padHeight,
          backgroundColor: notepadBg,
          borderRadius: "24px",
          border: `4px solid ${notepadBorder}`,
          boxShadow: "0 20px 40px rgba(0,0,0,0.08)",
          position: "relative",
          overflow: "hidden",
          transform: `scale(${notepadScale})`,
          opacity: notepadOpacity,
        }}
      >
        {/* Vertical Margin Line */}
        <div
          style={{
            position: "absolute",
            left: marginX,
            top: 0,
            width: "2px",
            height: vertLineHeight,
            backgroundColor: verticalLineColor,
            opacity: 0.6,
          }}
        />

        {/* Horizontal Ruled Lines */}
        {Array.from({ length: 8 }).map((_, i) => {
          const lineY = firstLineY + i * lineGap;
          const drawProgress = interpolate(
            frame,
            [lineDrawStart + i * 4, lineDrawStart + 20 + i * 4],
            [0, padWidth],
            { extrapolateRight: "clamp" }
          );

          return (
            <div
              key={`hline-${i}`}
              style={{
                position: "absolute",
                left: 0,
                top: lineY,
                height: "2px",
                width: drawProgress,
                backgroundColor: horizontalLineColor,
                opacity: 0.5,
              }}
            />
          );
        })}

        {/* Title */}
        <div
          style={{
            position: "absolute",
            top: titleY - 50, // offset baseline
            left: 0,
            width: "100%",
            textAlign: "center",
            fontSize: "65px",
            color: textColor,
            paddingLeft: padWidth * 0.05,
            paddingRight: padWidth * 0.05,
            // Wipe animation to simulate writing
            clipPath: `polygon(0 0, ${interpolate(frame, [titleDrawStart, titleDrawStart + 30], [0, 100], { extrapolateRight: "clamp" })}% 0, ${interpolate(frame, [titleDrawStart, titleDrawStart + 30], [0, 100], { extrapolateRight: "clamp" })}% 100%, 0 100%)`,
          }}
        >
          {title}
        </div>

        {/* List Items */}
        {items.map((item, index) => {
          const itemY = firstLineY + index * lineGap;
          const startFrame = listStart + index * itemStagger;
          
          // Number visibility
          const numOpacity = interpolate(frame, [startFrame, startFrame + 10], [0, 1], { extrapolateRight: "clamp" });
          
          // Text wiping
          const textStart = startFrame + 5;
          const textWipe = interpolate(frame, [textStart, textStart + 20], [0, 100], { extrapolateRight: "clamp" });

          return (
            <div
              key={index}
              style={{
                position: "absolute",
                top: itemY - 65, // Position text to sit roughly on the ruled line
                left: contentStartX,
                display: "flex",
                alignItems: "center",
                height: "80px", // fixed height container
              }}
            >
              {/* Number Container */}
              <div
                style={{
                  position: "relative",
                  width: "70px",
                  height: "70px",
                  display: "flex",
                  justifyContent: "flex-start",
                  alignItems: "center",
                }}
              >
                {/* Number */}
                <span style={{ fontSize: "50px", color: textColor, opacity: numOpacity, transform: "translateY(-4px)" }}>
                  {index + 1}.
                </span>
              </div>

              {/* Text */}
              <div
                style={{
                  marginLeft: "10px",
                  fontSize: "65px",
                  color: textColor,
                  clipPath: `polygon(0 0, ${textWipe}% 0, ${textWipe}% 100%, 0 100%)`,
                }}
              >
                {item.text}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default ListAnimation;